cd /home/user/rork-app && bun -e '
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { CloudFrontClient, CreateInvalidationCommand } from "@aws-sdk/client-cloudfront";
import { readFileSync } from "fs";

const s3 = new S3Client({ region: "us-east-1", credentials: {
  accessKeyId: "AKIATAJ2SEG452FXIEVE",
  secretAccessKey: "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",
}});

const cf = new CloudFrontClient({ region: "us-east-1", credentials: {
  accessKeyId: "AKIATAJ2SEG452FXIEVE",
  secretAccessKey: "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",
}});

const BUCKET = "ivxholding.com";
const DIST_ID = "E2Q2K5SP0LJ0AM"; // will verify below

// Content types for each file
const files = [
  { key: "index.html", path: "expo/ivxholding-landing/index.html", type: "text/html; charset=utf-8" },
  { key: "ivx-home-feed.js", path: "expo/ivxholding-landing/ivx-home-feed.js", type: "application/javascript" },
  { key: "ivx-reels.js", path: "expo/ivxholding-landing/ivx-reels.js", type: "application/javascript" },
];

// Upload each file
for (const f of files) {
  const body = readFileSync(f.path);
  console.log(`Uploading ${f.key} (${body.length} bytes)...`);
  await s3.send(new PutObjectCommand({
    Bucket: BUCKET,
    Key: f.key,
    Body: body,
    ContentType: f.type,
    CacheControl: "public, max-age=300, s-maxage=60",
  }));
  console.log(`  ✓ Uploaded ${f.key}`);
}

// Invalidate CloudFront
console.log(`\nInvalidating CloudFront distribution ${DIST_ID}...`);
try {
  const inv = await cf.send(new CreateInvalidationCommand({
    DistributionId: DIST_ID,
    InvalidationBatch: {
      CallerReference: `landing-deploy-${Date.now()}`,
      Paths: { Quantity: 3, Items: ["/index.html", "/ivx-home-feed.js", "/ivx-reels.js"] },
    },
  }));
  console.log(`  ✓ Invalidation ID: ${inv.Invalidation?.Id}`);
} catch (err) {
  console.log(`  ✗ CloudFront invalidation error: ${err.name} - ${err.message?.substring(0, 200)}`);
  console.log(`  (Files are uploaded — CF will refresh within ~5 min based on Cache-Control)`);
}
' 2>&1

